using sv_c0e14aabd06d416a9999747042e2aa53.Components;
using sv_c0e14aabd06d416a9999747042e2aa53.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = per-circuit in Blazor Server, so each user gets independent state.
builder.Services.AddScoped<WarehouseStateService>();
builder.Services.AddScoped<InventoryAlertService>();

