@rendermode InteractiveServer
@inject sv_c0e14aabd06d416a9999747042e2aa53.Services.WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" style="width:auto;"
        @bind="SelectedWarehouseId" @bind:event="onchange">
    @foreach (var wh in sv_c0e14aabd06d416a9999747042e2aa53.Services.WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string SelectedWarehouseId
    {
        get => WarehouseState.CurrentWarehouseId;
        set => WarehouseState.SetWarehouse(value);
    }

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject sv_c0e14aabd06d416a9999747042e2aa53.Services.InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentLowStockCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentLowStockCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

