@page "/dashboard"
@rendermode InteractiveServer
@inject sv_c0e14aabd06d416a9999747042e2aa53.Services.WarehouseStateService WarehouseState
@inject sv_c0e14aabd06d416a9999747042e2aa53.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">
    Viewing: <strong>@CurrentWarehouseName</strong>
</p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-secondary">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Active Warehouse</h5>
                <p class="display-6">@WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Polling Status</h5>
                <p class="display-6 text-success">● Active</p>
            </div>
        </div>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;

    private string CurrentWarehouseName =>
        sv_c0e14aabd06d416a9999747042e2aa53.Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling when the dashboard becomes visible.
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            while (await timer.WaitForNextTickAsync(token))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
                // OnAlertCountChanged event fires inside RefreshAlertCountAsync,
                // which notifies ALL subscribed components (sidebar badge, this page, etc.)
            }
        }, token);
    }

    private void OnWarehouseChanged()
    {
        // Restart polling for the new warehouse immediately.
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.CurrentWarehouseId);
            StateHasChanged();
            StartPolling();
        });
    }

    private void OnAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertChanged;
    }
}

